def use_case(slug, title, desc, h1, keywords, answer, industry, trigger, data, flow, logic, channels, measures, guardrails, case, related):
    return dict(
        path=f"use-cases/{slug}.html", title=title, desc=desc, h1=h1, kicker=f"Use case · {industry}", keywords=keywords, answer=answer,
        schema="Article", category="Use cases", date="2026-10-11", nav=h1.split(":")[0],
        sections=[
            ("How it works", figure(flow_svg(h1, flow), "Use-case flow from signal to measurement.")),
            ("Trigger and data needed", f"<p><strong>Trigger:</strong> {trigger}</p>" + '<ul class="checklist cols-2">' + "".join(f"<li>{d}</li>" for d in data) + "</ul>"),
            ("Audience and journey logic", '<ol class="steps">' + "".join(f"<li>{l}</li>" for l in logic) + "</ol>"),
            ("Channels", '<ul class="chips chips-light">' + "".join(f"<li>{c}</li>" for c in channels) + "</ul>"),
            ("How to measure it", '<ul class="checklist">' + "".join(f"<li>{m}</li>" for m in measures) + "</ul>"),
            ("Guardrails", '<ul class="checklist">' + "".join(f"<li>{g}</li>" for g in guardrails) + "</ul>"),
            ("See it in a case study", f'<p>This use case is implemented in the <a href="../{case}">related case study</a>.</p>' + pills(("Request an architecture review", "../lp/aep-architecture-review.html"), ("Learn to build it", "../training/index.html"))),
        ],
        faqs=[], related=related,
        sources=[("Adobe Journey Optimizer documentation", f"{EL}/journey-optimizer"), ("Real-Time CDP documentation", f"{EL}/experience-platform/rtcdp/home")],
    )


