def landing(slug, title, desc, h1, keywords, answer, interest, bullets, who, nav):
    return dict(
        path=f"lp/{slug}.html", title=title, desc=desc, h1=h1, kicker="Get started", keywords=keywords, answer=answer, nav=nav,
        schema="WebPage", interest=interest, landing=True, hero_cta=("Fill in the form", "#enquire-form"),
        sections=[
            ("Tell us what you need", '<div class="contact-grid lp-grid"><div><ul class="checklist">' + "".join(f"<li>{b}</li>" for b in bullets)
             + f'</ul><p><strong>Who it is for:</strong> {who}</p>' + pills(("Chat on WhatsApp", WHATSAPP_MSG), ("Download the brochure", BROCHURE))
             + '</div><div class="form-card" id="enquire-form">@@LP_FORM@@</div></div>'),
        ],
        faqs=[("Is there any cost to enquire?", "No. We reply with next steps; nothing is charged until you agree a proposal or enrol."),
              ("How quickly will you reply?", "Usually within two business days, or faster on WhatsApp.")],
        related=[],
    )


